// ===== CONFIGURACAO DA PLANTA =====
let enterpriseId = 1;

// Mapeamento: Prefixo do Tag -> UN_ID no banco
// Adicionar nova unidade = adicionar uma linha aqui
let unitMap = {
    'T600_00': 600,
    'T610_00': 610,
    'T620_00': 620,
    'T700_00': 700,
    'T710_00': 710,
    'T720_00': 720,
    'T200_00': 200,
    'T210_00': 210,
    'T300_00': 300,
    'T310_00': 310,
    'T400_00': 400,
    'T410_00': 410,
    'T500_00': 500,
    'T501_00': 501,
    'T510_00': 510,
    'T511_00': 511,
    'L501_00': 5011,
    'L502_00': 5012,
    'L600_00': 6001,
    'L610_00': 6101,
    'L700_00': 7001
};
// ===================================

let now = new Date().toISOString();
let rawTags = msg.payload;
let messages = [];

for (let prefix in unitMap) {
    let unId = unitMap[prefix];
    let staTag = prefix + '_MGT.STA.STA_ID';
    let stpTag = prefix + '_MGT.STA.STP_ID';
    let staVal = rawTags[staTag];
    let stpVal = rawTags[stpTag];
    let tags = {};
    if (staVal !== undefined) tags[staTag] = staVal;
    if (stpVal !== undefined) tags[stpTag] = stpVal;
    if (Object.keys(tags).length > 0) {
        messages.push({
            topic: 'prostart/telemetry',
            payload: JSON.stringify({
                ent_id: enterpriseId,
                un_id: unId,
                timestamp: now,
                tags: tags
            }),
            qos: 1,
            retain: true
        });
    }
}

return [messages];

// ===== CONFIGURACAO DA UNIDADE =====
let enterpriseId = 1;
let unitId = 801;
// ===================================

let envelope = {
    ent_id: enterpriseId,
    un_id: unitId,
    timestamp: new Date().toISOString(),
    tags: {}
};

envelope.tags['S44003_MGT.STA.UN_ID'] = Number(msg.payload);

msg.topic = 'prostart/telemetry';
msg.payload = JSON.stringify(envelope);
msg.qos = 1;
msg.retain = true;

return msg;

// ===== DICIONARIO DE MAPEAMENTO (tagMap) =====
// type: 'event' = UPDATE anterior + INSERT novo (so se mudou)
// type: 'point' = INSERT direto (leitura instantanea)
// O roteamento e por SUFIXO do tag (ultima parte apos o ponto final)
let tagMap = {
    'STA_ID': {
        type: 'event',
        table: 'status',
        idField: 'STA_ID',
        bgnField: 'STA_BGN',
        endField: 'STA_END'
    },
    'UN_ID': {
        type: 'event',
        table: 'status',
        idField: 'STA_ID',
        bgnField: 'STA_BGN',
        endField: 'STA_END'
    },
    'STP_ID': {
        type: 'event',
        table: 'steps',
        idField: 'STP_ID',
        bgnField: 'STP_BGN',
        endField: 'STP_END'
    }
    // Futuras expansoes:
    // 'PV': { type: 'point', table: 'telemetry' }
};
// =============================================

let env = JSON.parse(msg.payload);
let entId = env.ent_id;
let unId = env.un_id;
let now = new Date(env.timestamp);
let tags = env.tags;

let queries = [];

for (let tag in tags) {
    let val = Number(tags[tag]);

    // Extrai o sufixo do tag (ex: 'STA_ID' de 'T600_00_MGT.STA.STA_ID')
    let parts = tag.split('.');
    let suffix = parts[parts.length - 1];

    // Busca configuracao no tagMap pelo sufixo
    let cfg = tagMap[suffix];
    if (!cfg) continue;

    if (cfg.type === 'event') {
        let key = 'prev_' + cfg.table + '_' + unId + '_' + suffix;
        let prev = flow.get(key);

        if (prev === undefined) {
            // Primeira leitura: apenas INSERT (abre evento)
            flow.set(key, val);
            queries.push({
                query: 'INSERT INTO ' + cfg.table + 
                       ' (ENT_ID, UN_ID, ' + cfg.idField + ', ' + cfg.bgnField + ') ' +
                       'VALUES ($1, $2, $3, $4)',
                params: [entId, unId, val, now]
            });
        } else if (val !== prev) {
            // Mudou: UPDATE anterior (fecha) + INSERT novo (abre)
            flow.set(key, val);
            queries.push({
                query: 'UPDATE ' + cfg.table + 
                       ' SET ' + cfg.endField + ' = $1 ' +
                       'WHERE UN_ID = $2 AND ENT_ID = $3 AND ' + cfg.endField + ' IS NULL',
                params: [now, unId, entId]
            });
            queries.push({
                query: 'INSERT INTO ' + cfg.table + 
                       ' (ENT_ID, UN_ID, ' + cfg.idField + ', ' + cfg.bgnField + ') ' +
                       'VALUES ($1, $2, $3, $4)',
                params: [entId, unId, val, now]
            });
        }
        // Se val === prev: nao faz nada (economia de I/O)

    } else if (cfg.type === 'point') {
        // Point data: INSERT direto (sem fechamento)
        queries.push({
            query: 'INSERT INTO ' + cfg.table + 
                   ' (ENT_ID, UN_ID, TEL_NAM, TEL_VAL, TEL_BGN) ' +
                   'VALUES ($1, $2, $3, $4, $5)',
            params: [entId, unId, tag, val, now]
        });
    }
}

if (queries.length === 0) return null;

return [queries];
